export interface SignInItem{id:string;kind:'provider'|'site';name:string;host:string;iconHosts:string[];covers:string[];visits:number;bookmarked:boolean;saved:boolean;autofill:boolean;url:string;status:'todo'|'opened'|'done'|'skipped';by:''|'detected'|'manual'}
