/** "Report a problem" about a website or about Acira (desktop/browser-services/site-reports.cjs): what went wrong, and the exact message Send sends. */
export type SiteReportKind='blocked'|'broken'|'banner'|'other'|'app-broken'|'app-looks'|'app-crash'|'app-idea';
/** What a report is about: a website (its host is sent) or Acira itself (no site, the app-* problems, a required note). */
export type SiteReportSubject='site'|'app';
export interface SiteReportPayload{schema:1;host:string|null;kind:SiteReportKind;list:string|null;appVersion:string;platform:string;note:string}
/** Script blocking for the page's site: `blocked` is what applies now, `saved` is false in a private session (kept for that session only). `supported` is false in Tor, which has its own security levels. */
export interface PageScripts{supported:boolean;site:string;blocked:boolean;mode:'default'|'everywhere';saved:boolean}
/** The profile's script choices: the mode and both lists (sites cover their subdomains). */
export interface ProfileScripts{mode:'default'|'everywhere';blocked:string[];allowed:string[];limit:number}
/** Zap (Beta 14): a part of a page the person removed. `label` is the part's own words (may be empty: the kind's name is shown then). `hold` says how sure the rule is to last: 'firm' keeps it, 'loose' or 'frame' means the site may bring it back. */
export type ZapKind='frame'|'video'|'image'|'bar'|'popup'|'widget'|'block';
export interface ZapRule{host:string;id:string;label:string;kind:ZapKind;/** Milliseconds since the epoch. */at:number;hold:'firm'|'loose'|'frame'}
/** One page's removed parts. `supported` is false for pages Zap cannot work on (Acira's own, none open); `picking` while the picker is on. */
export interface ZapSiteStatus{supported:boolean;host:string;picking:boolean;private:boolean;rules:ZapRule[]}
/** Every site with removed parts, for the active profile (a private or Tor window: its own, kept in memory). */
export interface ZapSites{sites:{host:string;rules:ZapRule[]}[]}
