export interface MetricsStatus{marks?:UsageMarks;choice:'unset'|'on'|'off';enabled:boolean;configured:boolean;endpointHost:string;lastSent:string;/** Beta 14: when the last message was sent (ms; 0 = none), kept on this computer only. */lastSentAt?:number;sample:boolean;payload:Record<string,unknown>;/** Beta 14: what switching sharing off sends (shown on acira://usage). */offPayload?:Record<string,string|number>;/** Beta 14: the day the id is replaced (it is replaced every 28 days), 'YYYY-MM-DD'; empty while off. */idResetsOn?:string;/** Beta 14 (section C): the usage notice on the new-tab page. */notice?:UsageNotice;/** R4-61: "Ask me now and then how features are working". */askRatings?:boolean;/** The exact shape of a rating answer (example feature and stars). */ratingPayload?:Record<string,string|number>|null;/** Windows only: the one message the uninstaller sends when Acira is removed while this is on (null elsewhere). */uninstallPayload?:Record<string,string|number>|null}
/** The usage notice (brief section C): `visible` shows the banner; `pending` means X was pressed and Undo may still be on screen; `how` is what the first message will report (x, link, timeout, undoneThenX, none). */
export interface UsageNotice{applies:boolean;visible:boolean;pending:boolean;settled:boolean;how:''|'x'|'link'|'timeout'|'undoneThenX'|'none';expiresAt:number}
