export interface RemoteArtwork{id:string;src:string;name:string;artist:string;date:string;license:string;credit:string;source:string;collection:string}
export interface WebsiteLanguageStatus{profileId:string;privateMode:boolean;tor:boolean;choice:string[]|null;current:string[];preferred:string[];/** What a website can read now. */visible:string[];/** What it will read after a restart. */willSee:string[];restartRequired:boolean}
/** The Task manager's reading (desktop/task-manager.cjs): memory in KB, CPU in percent of one core (null until a second sample), tabs that share a process as one group. */
export interface TaskManagerReading{at:number;platform:string;tabs:{tabIds:string[];memoryKB:number;cpu:number|null}[];extensions:{id:string;name:string;memoryKB:number;cpu:number|null;/** a small PNG data URL, only in a reading asked with `icons`; '' when the extension has none */icon?:string}[];own:{id:'browser'|'interface'|'graphics'|'network'|'otherPages'|'other';memoryKB:number;cpu:number|null}[];total:{memoryKB:number;cpu:number|null}}
export interface ServiceResult{taskManager?:TaskManagerReading;/** search.suggest: the service asked and at most 5 plain-text suggestions; null when nothing was sent or nothing came back. */suggestions?:{service:{id:string;name:string};items:string[]}|null;/** search.opensearch: the engine the site advertises, or null. */opensearch?:{name:string;template:string;suggest?:string}|null;/** A local file path typed in the address bar (13.5): `handled` when main opened the file or refused the path, so the address bar does not search it. */typedFile?:{handled:boolean};/** Move to another computer (desktop/transfer/handle.cjs): one bag per request, src/features/transfer/types.ts. */transfer?:TransferResultBag;/** Live pull requests (desktop/live-prs): the folder's settings and rows. */livePrs?:LivePrsStatus;scripts?:PageScripts;scriptRules?:ProfileScripts;signin?:SignInPlan;websiteLanguages?:WebsiteLanguageStatus;vpn?:VpnStatus;remoteArtwork?:RemoteArtwork;seenArtwork?:RemoteArtwork[];connection?:ConnectionOptions;threat?:ThreatStatus|null;siteReport?:{available:boolean;reason?:'tor'|'unavailable'|'not-a-website';payload?:SiteReportPayload|null;sent?:boolean;/** Send, not taken: nothing answered ('offline'), or the server refused it or the hourly cap was reached ('later'). */failure?:'offline'|'later'};favicons?:Record<string,string>;cleanup?:ProfileCleanupSaveResult;cleanupGate?:ProfileCleanupGate;network?:NativeNetworkStatus;protection?:ProtectionSummary;antiTracking?:AntiTrackingStatus;safeBrowsing?:SafeBrowsingStatus;update?:UpdateStatus;/** 14.3 (Settings > Appearance, Seasonal app icon): the person's switch (on unless turned off), whether this run asks at all (a packaged app), and the name of the icon on screen. */appIcon?:{enabled:boolean;live:boolean;name:string|null};proxy?:ProxyStatus;https?:HttpsOnlyStatus;dataClear?:BrowsingDataStatus;dataCleared?:BrowsingDataResult;forgetPreview?:ForgetSitePreview;forgotten?:ForgetSiteResult;artwork?:PersonalArtworkLibrary;/** 14.4: artwork.video*: the profile's video (null when none); artwork.video-import: the copied file waiting for its check, or cancelled. */artworkVideo?:import('./connectedServices').OwnVideoAnswer;/** 14.4: power.state */power?:{onBattery:boolean;lowPower:boolean};reader?:ReaderArticle|{available:false;reason:string};site?:SiteStatus;siteClear?:SiteClearResult;connectionCertificate?:ConnectionCertificate;extensionToolbar?:ExtensionToolbarTarget;filterLists?:FilterListsStatus;reloadRequired?:boolean;certificate?:CertificateStatus;filters?:ContentFilters;downloads?:BrowserDownload[];cancelled?:boolean;exported?:boolean;sources?:ImportSource[];/** imports.discover: installed browsers' own app icons (PNG data URLs) keyed by browser name; a browser with no readable executable has no entry. */icons?:Record<string,string>;/** imports.discover: source ids any local profile has imported from (not undone). */imported?:string[];batches?:ImportBatch[];batch?:ImportBatch;preview?:{source:ImportSource;bookmarks:number;history:number|null;/** What the import leaves out and why (desktop/imports.cjs preview): pages already saved or met twice, and addresses that are not web pages. */skipped?:Record<'bookmarks'|'history',{duplicates:number;notWeb:number}>;favorites?:number;spaces?:number;pinned?:number;/** Opera, Vivaldi, Zen: open tabs in all (pinned ones included). */tabs?:number;/** What the Favorites come from: Arc's Favorites, a speed dial, Zen's Essentials. */favoritesFrom?:'favorites'|'speedDial'|'essentials';/** What this import would leave behind, before it runs. */notBrought?:ImportNote[];/** Safari: macOS has not given Acira access to its data yet. */permission?:'needed';extensions:{id:string;name:string;version:string;manifestVersion:number}[];warnings:string[]};privacy?:{site?:string|null;blocking:boolean;/** Protection turned off for this site itself (not only ad blocking for the profile): banner hiding and phishing-listed page resources follow it too. */siteOff?:boolean;/** Warnings before opening a listed or look-alike page are on (Settings, Privacy); they stay on with the site's protection off. */warnings?:boolean;thirdPartyCookiesBlocked?:boolean;profileBlocking?:boolean;blocked?:number;filters?:string;thirdPartyCookies?:string;details?:{hostname:string;type:string;action:string;time:number}[]};undone?:boolean;metrics?:MetricsStatus;notice?:UsageNotice;rating?:RatingFeature|null;ratingSent?:boolean;/** Beta 14, Zap: one page's removed parts (zap.site, zap.restore, zap.restore-all, zap.start) or every site's (zap.list, zap.restore-rule, zap.restore-site, zap.clear). */zap?:ZapSiteStatus|ZapSites}
export type SearchEngine = 'google' | 'duckduckgo' | 'bing';
export type Appearance = 'light' | 'dark' | 'system';
export interface BrowserProfile { id: string; name: string; /** The name Acira gave this profile itself (the first profile's "Personal", then that word in the first setup's language). The profile still has its default name only while `name` equals it; dropped when the person renames it or the first setup ends. */ defaultName?: string; color: string; avatar?: string; /** PNG/JPEG data URL, at most 64 KB and 256 px. */ picture?: string; /** Shown under the name; never sent to websites. */ email?: string; partition: string; private?: boolean; /** Private window with Tor (stream N): all traffic through the bundled Tor engine. */ tor?: boolean; /** Its own appearance and search engine (profileSettings.ts); unset ones follow the global settings. */ settings?: ProfileSettings; /** Beta 14 (AF): the websites pinned to open in the side panel, at most six, in order (runtime/sidePanelSites.ts). Per profile; saved with the profile, so a transfer takes them along. */ sidePanelSites?: SidePanelSite[] }
export type TabGroupColor = 'none' | 'grey' | 'blue' | 'red' | 'yellow' | 'green' | 'pink' | 'purple' | 'cyan' | 'orange';
export interface TabGroup { id: string; name: string; color: TabGroupColor; /** Beta 14 (section M): true = the folder takes its colour from the sites inside it (the sidebar works it out); false = the person picked `color`. Absent on groups saved before Beta 14: see isAutoGroup (runtime/tabGroups.ts). */ auto?: boolean; collapsed: boolean; /** Beta 14, pinned folders (runtime/pinnedFolders.ts): a top-level folder that lives in the Pinned block. Its tabs keep `pinned:false`; they count as pinned because their folder is. An inner folder has none: it stands where its parent stands. */ pinned?: true; /** Beta 14 (section AE): the id of the top-level group this one stands inside; absent = a top-level group. One level only (runtime/groupNesting.ts). 13.8 ignores it: the group stays, as a top-level one. */ parentGroupId?: string; browserProfileId: string; lastActiveTabId?:string; /** The workspace it lives in; absent = the profile's first workspace (runtime/workspaces.ts). */ workspaceId?:string; /** Profiles as spaces (runtime/profileSpaces.ts): the put-away workspace this group stands for while profiles are spaces, the name it was given then (a different name now means the person renamed it), and, for one of that workspace's own groups, its name there (absent: the group of the workspace's loose tabs). */ fromWorkspaceId?:string; fromName?:string; fromGroup?:string }
/** A workspace (R3-57): a mode inside one profile. Its tabs, pinned tabs, groups and splits stay in the window's lists, tagged with `workspaceId`; the profile keeps sign-ins, history and bookmarks. `name` is empty for the first workspace nobody renamed (shown as "Main"); `icon` is a glyph id (WORKSPACE_GLYPHS) or one letter or emoji; `color` is #rrggbb and tints the window frame while the workspace is open. */
export interface Workspace { id: string; name: string; browserProfileId: string; icon?: string; color?: string; /** R3-38 Secured workspace (the one isolated kind): its tabs share one memory-only session, are `privacy: 'secured'` (never saved in the window state, history, Rewind or closed tabs) and live in a sealed file (desktop/browser-services/secured-vault.cjs) while it is locked. */ secured?: true; /** Set by main only after Windows Hello (desktop/secured-workspaces.cjs). Never saved: a secured workspace always starts locked. While locked it has no tabs at all, only the lock screen (acira://locked). */ unlocked?: true; /** Profiles as spaces (runtime/profileSpaces.ts): put away while profiles are spaces, its tabs shown as tab groups in its profile's space; it comes back when workspaces do. */ parked?: true }
/** A deleted workspace waiting for its Undo: its tabs are in `closedTabs` under `batch`. */
export interface ClosedWorkspace { workspace: Workspace; index: number; batch: string; groups: TabGroup[] }
/** What a closed split pane remembers of its split, so Undo puts it back into the split at its slot (not only into its group). */
export interface ClosedSplit { split: SplitGroup; slot: number; shown: boolean }
export interface ClosedTabSession extends TabSession { closedSplit?: ClosedSplit; closedIndex?: number; closedLeftId?: string; closedRightId?: string; closedBatch?: string; closedActive?: boolean; /** The window revision at which it closed: orders a normal close against a private one (Ctrl+Shift+T takes the newest of both). */closedRev?: number }
/** A toast's one text action (bible §4: "Tab closed · Undo"); the command is dispatched as-is and validated in main. */
/** A status pill's glyph (bible §4 Transient surfaces): "AI-free mode on" uses shield. */
export type StatusIcon = 'check' | 'shield' | 'sparkles' | 'sparkles-off' | 'info' | 'error' | 'workspace';
/** One row of a page/link right-click menu shown as an Acira menu (main keeps the action; the row carries its id). */
export interface PageMenuItem { id?: string; label?: string; enabled?: boolean; checked?: boolean; type?: 'separator'; /** A gesture or key shown at the row's end ('Shift+Click'). */ shortcut?: string; /** Beta 14: a second, quieter line under the label (the first-use image search chooser says what each service is good for). */ detail?: string; /** An extension's item: its icon (a data URL), how far it sits in (a group's children), a heading row that only names its group, and a check or radio mark that closes the menu on click. */ icon?: string; depth?: number; header?: boolean; mark?: 'check' | 'dot' | 'none' }
export interface ToastAction { label: string; /** A catalog id for the label; the interface shows it in the current language and falls back to `label`. */labelId?: string; /** The label's parameters ("Open in {name}"). */labelParams?: Record<string, string | number>; command: BrowserAction; /** A Settings control id to land on when the action opens Settings (handed over in the interface, since page addresses cannot carry it). */ settings?: string }
